/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 10/01/2023
/// Base Price Version.
/// </summary>
final class METGUPItemBasePriceTableEventHandler
{
}

Method.Source:
/// <summary>
/// Inserted hanlder
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">event</param>
[DataEventHandler(tableStr(GUPItemBasePrice), DataEventType::Inserted)]
public static void GUPItemBasePrice_onInserted(Common sender, DataEventArgs e)
{
    METGUPItemBasePriceTableEventHandler::metProcessTrackChange(sender);
}

    /// <summary>
    /// Process the change track
    /// Kept this process light weight due to volume of records
    /// </summary>
    public static void metProcessTrackChange(Common _sender)
    {
        METPriceChangeTracking  priceChangeTracking;
        GUPItemBasePrice        itemBasePrice = _sender as GUPItemBasePrice;

        try
        {
            if (itemBasePrice.PriceType == GUPBasePriceType::BasePriceInventoryCost)
            {
                ttsbegin;
                priceChangeTracking.clear();
                                
                priceChangeTracking.SourceCrud  = SysAppCRUDOperation::Create;
                priceChangeTracking.ChangeType  = METPriceChangeType::BasePrice;
                priceChangeTracking.TrackingId  = METPriceChangeEvent::getNumberSeq();
                priceChangeTracking.RefRecId    = itemBasePrice.recId;
                priceChangeTracking.RefTableId  = itemBasePrice.tableId;
                priceChangeTracking.QuantityAmountFrom = itemBasePrice.PriceQty ? itemBasePrice.PriceQty : 1;

                priceChangeTracking.VersionId   = itemBasePrice.VersionId;
                priceChangeTracking.InventSiteID = InventDim::find(itemBasePrice.InventDimId).InventSiteId;
                priceChangeTracking.ItemId      = itemBasePrice.ItemId;
                priceChangeTracking.FromDate    = itemBasePrice.FromDate ? itemBasePrice.FromDate : DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
                priceChangeTracking.ToDate      = itemBasePrice.ToDate;
                priceChangeTracking.Price       = itemBasePrice.Price;
                priceChangeTracking.PriceQty    = itemBasePrice.PriceQty;
                priceChangeTracking.UnitId      = itemBasePrice.UnitId;
                priceChangeTracking.VendAccount = itemBasePrice.AccountRelation;

                priceChangeTracking.insert();
                ttscommit;
            }
        }
        catch
        {
            Error("@MET:PriceChangeTrackingCreationFailed");
        }
    }
